#pragma once

// ui-assets - the binary assets the Ember look embeds in the app, as C arrays generated by
// tools/embed-assets.py into src/assets/ (the same way the library embeds its icon font, see
// libs/simple-lib-app/src/ui/icon-data.c). Fonts open with openFontMemory(), textures with
// loadGfxTextureMem(), which tells PNG from JPEG by the file header.

// Manrope, SIL Open Font License 1.1 (src/assets/OFL.txt): one file per weight, one shared character set
// (include/manrope-coverage.h says which codepoints it can draw).
extern const unsigned char manropeRegularData[];     // 400
extern const unsigned int  manropeRegularDataSize;
extern const unsigned char manropeSemiBoldData[];    // 600
extern const unsigned int  manropeSemiBoldDataSize;
extern const unsigned char manropeBoldData[];        // 700
extern const unsigned int  manropeBoldDataSize;
extern const unsigned char manropeExtraBoldData[];   // 800
extern const unsigned int  manropeExtraBoldDataSize;

// Helper textures: white, 8-bit RGBA, the shape lives in the alpha channel; tinted when drawn.
extern const unsigned char texRoundR8Data[];         // 32x32, filled, radius 8 (caps 8): badges, key chips
extern const unsigned int  texRoundR8DataSize;
extern const unsigned char texRoundR16Data[];        // 48x48, filled, radius 16 (caps 16): cards, rows, segments
extern const unsigned int  texRoundR16DataSize;
extern const unsigned char texRoundR28Data[];        // 64x64, filled, radius 28 (caps 28): panels, pills
extern const unsigned int  texRoundR28DataSize;
extern const unsigned char texCornerR14Data[];       // 14x14, outer corner, top left: image corners radius 14
extern const unsigned int  texCornerR14DataSize;
extern const unsigned char texCornerR16Data[];       // 16x16, outer corner, top left: image corners radius 16
extern const unsigned int  texCornerR16DataSize;
extern const unsigned char texRingR20W3Data[];       // 48x48, ring 3 px, outer radius 20 (caps 20)
extern const unsigned int  texRingR20W3DataSize;
extern const unsigned char texRingR23W4Data[];       // 64x64, ring 4 px, outer radius 23 (caps 24)
extern const unsigned int  texRingR23W4DataSize;
extern const unsigned char texRingR25W4Data[];       // 64x64, ring 4 px, outer radius 25 (caps 24)
