extern const unsigned char texRingR34W4Data[];       // 80x80, ring 4 px, outer radius 34 (caps 36)
extern const unsigned int  texRingR34W4DataSize;
extern const unsigned char texGlowR23Data[];         // 192x192, soft glow around a radius-23 rectangle (caps 95)
